// Player-facing UI preferences shared by the top-bar settings menu and the
// surfaces they control. Keep these separate from wallet/account state: the
// choices belong to this browser and should survive disconnects.

export const REVEAL_AUTO_OPEN_STORAGE_KEY = 'degenerus:reveal-tray:auto-open:v1';
export const ALL_IN_BUTTON_STORAGE_KEY = 'degenerus:all-in-button:v1';
export const AFKING_LOW_FUND_WARNING_STORAGE_KEY = 'degenerus:afking-low-fund-warning:v1';
export const BIGGEST_BOUNTIES_MODE_STORAGE_KEY = 'degenerus:biggest-bounties:mode:v1';
export const LIGHTWEIGHT_MODE_STORAGE_KEY = 'degenerus:lightweight-mode:v1';
let _lightweightFallback = false;

export function readLightweightModePreference() {
  try {
    return globalThis.localStorage
      ? globalThis.localStorage.getItem(LIGHTWEIGHT_MODE_STORAGE_KEY) === '1'
      : _lightweightFallback;
  } catch (_) { return _lightweightFallback; }
}

export function syncLightweightMode(root = globalThis.document) {
  root?.documentElement?.classList?.toggle('lightweight-mode', readLightweightModePreference());
}

export function writeLightweightModePreference(enabled) {
  const value = Boolean(enabled);
  _lightweightFallback = value;
  _write(LIGHTWEIGHT_MODE_STORAGE_KEY, value ? '1' : '0');
  syncLightweightMode();
  _emit('lightweightMode', value);
  return value;
}

// Imported before components start optional reads, including on a cold load.
syncLightweightMode();

const _listeners = new Set();

function _storage() {
  try { return globalThis.localStorage || null; }
  catch (_error) { return null; }
}

function _read(key) {
  try { return _storage()?.getItem(key) ?? null; }
  catch (_error) { return null; }
}

function _write(key, value) {
  try { _storage()?.setItem(key, value); }
  catch (_error) { /* private mode: keep the live in-memory choice */ }
}

function _emit(name, value) {
  const detail = Object.freeze({ name, value });
  for (const listener of _listeners) {
    try { listener(detail); } catch (_error) { /* one consumer cannot break another */ }
  }
}

export function readRevealAutoOpenPreference() {
  return _read(REVEAL_AUTO_OPEN_STORAGE_KEY) === '1';
}

export function writeRevealAutoOpenPreference(enabled) {
  const value = Boolean(enabled);
  _write(REVEAL_AUTO_OPEN_STORAGE_KEY, value ? '1' : '0');
  _emit('revealAutoOpen', value);
  return value;
}

// Preserve the historical ALL IN behavior unless the player explicitly hides
// it. Eligibility remains a separate live account check in the buy widget.
export function readAllInButtonPreference() {
  return _read(ALL_IN_BUTTON_STORAGE_KEY) !== '0';
}

export function writeAllInButtonPreference(enabled) {
  const value = Boolean(enabled);
  _write(ALL_IN_BUTTON_STORAGE_KEY, value ? '1' : '0');
  _emit('allInButton', value);
  return value;
}

// A running subscription can silently exhaust its prepaid balance, so the
// below-seven-days warning is on unless this browser explicitly hides it.
export function readAfkingLowFundWarningPreference() {
  return _read(AFKING_LOW_FUND_WARNING_STORAGE_KEY) !== '0';
}

export function writeAfkingLowFundWarningPreference(enabled) {
  const value = Boolean(enabled);
  _write(AFKING_LOW_FUND_WARNING_STORAGE_KEY, value ? '1' : '0');
  _emit('afkingLowFundWarning', value);
  return value;
}

// ON is the historical/default behavior. VIEW preserves the useful records and
// live pool while removing every transaction shortcut; OFF removes the rail.
export function readBiggestBountiesModePreference() {
  const stored = _read(BIGGEST_BOUNTIES_MODE_STORAGE_KEY);
  return stored === 'view' || stored === 'off' ? stored : 'on';
}

export function writeBiggestBountiesModePreference(mode) {
  const value = mode === 'view' || mode === 'off' ? mode : 'on';
  _write(BIGGEST_BOUNTIES_MODE_STORAGE_KEY, value);
  _emit('biggestBountiesMode', value);
  return value;
}

export function subscribeUiPreferences(listener) {
  if (typeof listener !== 'function') return () => {};
  _listeners.add(listener);
  return () => _listeners.delete(listener);
}
